INSERT INTO lt_videos (id, sort, data) VALUES
  ('good-life', 0, '{"id":"good-life","yt":"8KkKuTCFvzI","cat":"mental","cats":["bluezones"],"level":"입문","format":"강연","title":"좋은 삶을 만드는 것은 무엇인가 — 가장 긴 행복 연구의 교훈","orig":"What Makes a Good Life? Lessons from the Longest Study on Happiness","speaker":"Robert Waldinger","channel":"TED","desc":"75년 넘게 이어진 하버드 성인발달연구의 책임자 로버트 월딩어가 ''무엇이 우리를 건강하고 행복하게 하는가''에 대해 연구가 얻은 교훈을 이야기합니다. TED 역대 최다 조회 강연 중 하나.","tags":["행복","관계","하버드연구"]}'),
  ('stress-friend', 1, '{"id":"stress-friend","yt":"RcGyVTAoXEU","cat":"mental","level":"입문","format":"강연","title":"스트레스를 친구로 만드는 법","orig":"How to Make Stress Your Friend","speaker":"Kelly McGonigal","channel":"TED","desc":"스탠퍼드 건강심리학자 켈리 맥고니걸이 스트레스를 바라보는 관점이 건강에 미치는 영향, 그리고 사람과의 연결이 스트레스 회복력을 높이는 원리를 이야기합니다. TED 최다 조회 강연 중 하나.","tags":["스트레스","회복력","심리학"]}'),
  ('sleep-superpower', 2, '{"id":"sleep-superpower","yt":"5MuIMqhT8DM","cat":"sleep","cats":["mental"],"level":"입문","format":"강연","title":"수면은 당신의 초능력이다","orig":"Sleep Is Your Superpower","speaker":"Matt Walker","channel":"TED","desc":"UC버클리 수면과학자 매슈 워커가 수면이 학습·기억·면역·심혈관 건강에 미치는 영향과 수면 부족의 대가를 설명합니다.","tags":["수면","기억","면역"]}'),
  ('sugar-brain', 3, '{"id":"sugar-brain","yt":"lEXBxijQREo","cat":"metabolism","cats":["mental"],"level":"입문","format":"애니메이션","title":"설탕은 뇌에 어떤 영향을 줄까","orig":"How sugar affects the brain","speaker":"Nicole Avena","channel":"TED-Ed","desc":"신경과학자 니콜 아베나의 TED-Ed 수업. 설탕이 뇌의 보상 회로를 어떻게 자극하는지 5분 애니메이션으로 설명합니다.","tags":["설탕","보상회로","애니메이션"]}'),
  ('stress-body', 4, '{"id":"stress-body","yt":"v-t1Z5-oPtU","cat":"mental","cats":["heart"],"level":"입문","format":"애니메이션","title":"스트레스가 몸에 미치는 영향","orig":"How stress affects your body","speaker":"Sharon Horesh Bergquist","channel":"TED-Ed","desc":"몸에 내장된 스트레스 반응이 만성화되면 심장, 혈관, 면역, 소화기에 어떤 변화가 생기는지 TED-Ed 애니메이션으로 설명합니다.","tags":["스트레스","코르티솔","애니메이션"]}'),
  ('exercise-brain', 5, '{"id":"exercise-brain","yt":"BHY0FxzoKZE","cat":"mental","cats":["bluezones"],"level":"입문","format":"강연","title":"운동이 뇌를 바꾸는 놀라운 효과","orig":"The Brain-Changing Benefits of Exercise","speaker":"Wendy Suzuki","channel":"TED","desc":"신경과학자 웬디 스즈키가 운동이 기분·집중력·기억력, 그리고 장기적인 뇌 건강에 어떤 변화를 주는지 자신의 경험과 연구로 풀어냅니다.","tags":["운동","해마","기분"]}'),
  ('live-100', 6, '{"id":"live-100","yt":"I-jk9ni4XWk","cat":"bluezones","cats":["metabolism"],"level":"입문","format":"강연","title":"100세 넘게 사는 법 — 블루존의 비밀","orig":"How to Live to Be 100+","speaker":"Dan Buettner","channel":"TED","desc":"댄 뷰트너와 연구팀이 찾아낸 장수 마을 ''블루존''(오키나와, 사르데냐 등) 사람들의 공통된 생활 습관을 소개합니다.","tags":["블루존","오키나와","생활습관"]}'),
  ('blue-zones-netflix', 7, '{"id":"blue-zones-netflix","yt":"ahLcnJwQPTM","cat":"bluezones","cats":["metabolism"],"level":"입문","format":"다큐","title":"100세 장수의 비밀: 블루존 — 공식 예고편","orig":"LIVE TO 100: SECRETS OF THE BLUE ZONES - Official Trailer","speaker":"Dan Buettner","channel":"Netflix","desc":"댄 뷰트너가 세계의 장수 마을을 찾아가는 넷플릭스 4부작 다큐멘터리 시리즈의 예고편.","tags":["블루존","넷플릭스","다큐"]}'),
  ('lustig-sugar', 8, '{"id":"lustig-sugar","yt":"dBnniua6-oM","cat":"metabolism","level":"중급","format":"강연","title":"설탕: 쓰디쓴 진실","orig":"Sugar: The Bitter Truth","speaker":"Robert Lustig","channel":"University of California Television (UCTV)","desc":"UCSF 소아내분비학 교수 로버트 러스티그의 유명한 강의. 과당이 대사 질환에 어떤 역할을 하는지 생화학적으로 설명합니다. 일부 주장에 대한 반론도 있으니 함께 참고하세요.","tags":["설탕","과당","대사질환"]}'),
  ('why-age', 9, '{"id":"why-age","yt":"GoJsr4IwCm4","cat":"aging","level":"입문","format":"애니메이션","title":"왜 늙는가? 노화를 영원히 끝내야 할까?","orig":"Why Age? Should We End Aging Forever?","speaker":"Kurzgesagt","channel":"Kurzgesagt – In a Nutshell","desc":"노화가 세포 수준에서 어떻게 일어나는지, 그리고 노화를 치료 대상으로 보는 관점과 그에 따른 윤리적 질문을 애니메이션으로 설명합니다.","tags":["노화기전","텔로미어","애니메이션"]}'),
  ('cure-aging', 10, '{"id":"cure-aging","yt":"MjdpR-TY6QU","cat":"aging","level":"입문","format":"애니메이션","title":"노화를 치료할 수 있을까?","orig":"How to Cure Aging","speaker":"Kurzgesagt","channel":"Kurzgesagt – In a Nutshell","desc":"노화세포, 세포 리프로그래밍 등 노화를 늦추거나 되돌리려는 연구 방향을 애니메이션으로 쉽게 정리합니다.","tags":["노화세포","리프로그래밍","애니메이션"]}'),
  ('stress-brain', 11, '{"id":"stress-brain","yt":"WuyPuH9ojCE","cat":"mental","level":"입문","format":"애니메이션","title":"스트레스가 뇌에 미치는 영향","orig":"How stress affects your brain","speaker":"Madhumita Murgia","channel":"TED-Ed","desc":"만성 스트레스가 뇌의 구조와 기능, 기억에 어떤 변화를 일으키는지 다룬 TED-Ed 수업.","tags":["스트레스","해마","애니메이션"]}'),
  ('walker-doac', 12, '{"id":"walker-doac","yt":"Us8n8VBQn_c","cat":"sleep","cats":["mental"],"level":"입문","format":"팟캐스트","title":"세계 최고 수면 전문가: 꼭 필요한 6가지 수면 습관","orig":"The World''s No.1 Sleep Expert: The 6 Sleep Hacks You NEED! Matthew Walker","speaker":"Matt Walker","channel":"The Diary Of A CEO","desc":"매슈 워커와 스티븐 바틀렛의 2시간 대담. 크로노타입, 낮잠, 카페인, 수면제, 잠들기 전 휴대폰 사용 등을 다룹니다.","tags":["수면습관","카페인","크로노타입"]}'),
  ('walker-jre', 13, '{"id":"walker-jre","yt":"pwaWilO_Pig","cat":"sleep","cats":["mental"],"level":"입문","format":"팟캐스트","title":"조 로건 익스피리언스 #1109 — 매슈 워커","orig":"Joe Rogan Experience #1109 - Matthew Walker","speaker":"Matt Walker","channel":"PowerfulJRE","desc":"UC버클리 인간수면과학센터 설립자 매슈 워커가 조 로건과 수면 부족의 영향, 꿈, 알코올·대마와 렘수면 등 수면의 모든 것을 이야기합니다.","tags":["수면","렘수면","음주"]}'),
  ('huberman-sleep', 14, '{"id":"huberman-sleep","yt":"nm1TxQj9IsQ","cat":"sleep","cats":["mental"],"level":"중급","format":"팟캐스트","title":"수면을 지배하고 깨어 있을 때 더 또렷해지는 법","orig":"Master Your Sleep & Be More Alert When Awake","speaker":"Andrew Huberman","channel":"Huberman Lab","desc":"스탠퍼드 신경과학자 앤드루 휴버먼이 아데노신, 일주기 리듬, 아침 햇빛, 낮잠 등 수면과 각성을 조절하는 원리와 실천법을 다룹니다.","tags":["수면","생체리듬","햇빛"]}'),
  ('huberman-lex', 15, '{"id":"huberman-lex","yt":"ClxRHJPz8aQ","cat":"sleep","cats":["mental","metabolism"],"level":"중급","format":"팟캐스트","title":"앤드루 휴버먼: 수면, 꿈, 창의성, 단식, 신경가소성","orig":"Andrew Huberman: Sleep, Dreams, Creativity, Fasting, and Neuroplasticity","speaker":"Andrew Huberman","channel":"Lex Fridman Podcast","desc":"스탠퍼드 신경과학자 휴버먼이 렉스 프리드먼과 수면·꿈·단식·신경가소성에 대해 나눈 대화(#164).","tags":["수면","신경가소성","단식"]}'),
  ('bryan-jubilee', 16, '{"id":"bryan-jubilee","yt":"sPCZhLCkJaY","cat":"aging","level":"입문","format":"토론","title":"브라이언 존슨 vs 회의론자 20명","orig":"Bryan Johnson vs 20 Skeptics | Surrounded","speaker":"Bryan Johnson","channel":"Jubilee","desc":"''죽지 않기''를 목표로 극단적인 노화 역전 프로토콜을 실천하는 브라이언 존슨이 회의론자 20명과 토론합니다. 찬반 양쪽 시각을 함께 볼 수 있습니다.","tags":["바이오해킹","토론","생체나이"]}'),
  ('picard-huberman', 17, '{"id":"picard-huberman","yt":"nMkQUlBtFlk","cat":"mito","cats":["aging","mental"],"level":"중급","format":"팟캐스트","title":"마틴 피카드: 미토콘드리아를 최적화해 에너지와 수명을 높이는 법","orig":"Improve Energy & Longevity by Optimizing Mitochondria | Dr. Martin Picard","speaker":"Martin Picard","channel":"Huberman Lab","desc":"컬럼비아대 미토콘드리아 정신생물학 연구소장 마틴 피카드. 몸의 에너지는 ''예산''처럼 배분되며, 미토콘드리아는 에너지 생산뿐 아니라 스트레스 반응도 조절한다는 관점에서 스트레스·수면·식단·운동이 노화와 염증에 미치는 영향을 다룹니다.","tags":["미토콘드리아","에너지","스트레스"]}'),
  ('wahls-mito', 18, '{"id":"wahls-mito","yt":"KLjgBLwH3Wc","cat":"mito","cats":["metabolism"],"level":"입문","format":"강연","title":"미토콘드리아를 돌보라","orig":"Minding your mitochondria | Dr. Terry Wahls | TEDxIowaCity","speaker":"Terry Wahls","channel":"TEDx Talks","desc":"다발성경화증 환자이기도 한 의사 테리 월스가 영양 중심 식단으로 자신의 증상을 관리한 경험을 이야기합니다. ※ TED 측에서 개인 경험에 기반한 건강 조언이라는 주의 문구를 붙인 강연입니다.","tags":["미토콘드리아","식단","자가면역"]}'),
  ('ornish-diet', 19, '{"id":"ornish-diet","yt":"CbVflDOWCbU","cat":"heart","cats":["metabolism"],"level":"입문","format":"강연","title":"식단으로 치유하기","orig":"Dean Ornish: Healing through diet","speaker":"Dean Ornish","channel":"TED","desc":"생활습관 개선으로 심장병을 되돌릴 수 있음을 연구로 보여준 딘 오니시가 몸의 자연 치유력을 활용하는 간단하고 저렴한 방법을 이야기합니다.","tags":["심장병","생활습관의학","식단"]}'),
  ('sinclair-tedx', 20, '{"id":"sinclair-tedx","yt":"vCCdmGKtxPA","cat":"aging","level":"입문","format":"강연","title":"노화를 치료할 수 있을까?","orig":"A Cure for Ageing?: David Sinclair at TEDxSydney","speaker":"David Sinclair","channel":"TEDx Talks","desc":"데이비드 싱클레어가 TEDxSydney에서 노화를 늦추는 연구와 그 가능성에 대해 강연합니다.","tags":["노화치료","시르투인","TEDx"]}'),
  ('degrey-tedx', 21, '{"id":"degrey-tedx","yt":"qMAwnA5WvLc","cat":"aging","level":"중급","format":"강연","title":"노화 되돌리기","orig":"Undoing aging: Aubrey de Grey at TEDxDanubia 2013","speaker":"Aubrey de Grey","channel":"TEDx Talks","desc":"노화를 치료 가능한 상태로 보고 손상을 복구하자는 ''SENS'' 접근을 주장하는 오브리 드 그레이의 강연. 과학계에서 논쟁적인 관점입니다.","tags":["SENS","노화치료","TEDx"]}'),
  ('kennedy-tedx', 22, '{"id":"kennedy-tedx","yt":"iGSkpIRs6pc","cat":"aging","level":"입문","format":"강연","title":"더 오래 건강하게: 건강수명 vs 수명","orig":"Live Healthy Longer: Healthspan vs. Lifespan: Brian Kennedy at TEDxMaui 2013","speaker":"Brian Kennedy","channel":"TEDx Talks","desc":"벅 노화연구소 소장이었던 브라이언 케네디가 ''얼마나 오래''보다 ''얼마나 건강하게''가 중요한 이유, 건강수명(healthspan)의 개념을 설명합니다.","tags":["건강수명","healthspan","TEDx"]}'),
  ('huberman-sleep-essentials', 23, '{"id":"huberman-sleep-essentials","yt":"lIo9FcrljDk","cat":"sleep","level":"입문","format":"팟캐스트","title":"[요약판] 수면 마스터하기 — 핵심만 30분","orig":"Essentials: Master Your Sleep & Be More Alert When Awake","speaker":"Andrew Huberman","channel":"Huberman Lab","desc":"위 수면 에피소드의 핵심만 약 30분으로 압축한 Essentials 버전. 아데노신, 코르티솔·멜라토닌, 아침 빛 노출, 낮잠을 정리합니다.","tags":["수면","요약","멜라토닌"]}'),
  ('attia-huberman', 24, '{"id":"attia-huberman","yt":"ufsIA5NARIo","cat":"bluezones","cats":["aging"],"level":"중급","format":"팟캐스트","title":"피터 아티아: 활력·몸과 마음의 건강·수명을 개선하는 법","orig":"Dr. Peter Attia: Improve Vitality, Emotional & Physical Health & Lifespan","speaker":"Peter Attia","channel":"Huberman Lab","desc":"『Outlive』 저자 피터 아티아가 휴버먼과 함께 운동, 영양, 정서 건강을 아우르는 장수 전략을 길게 이야기합니다.","tags":["장수전략","운동","Outlive"]}'),
  ('attia-doac', 25, '{"id":"attia-doac","yt":"ZxXruY7llcc","cat":"bluezones","cats":["aging"],"level":"입문","format":"팟캐스트","title":"피터 아티아: 아무도 말하지 않는 노화 방지법","orig":"Peter Attia: Anti-aging Cure No One Talks About!","speaker":"Peter Attia","channel":"The Diary Of A CEO","desc":"스티븐 바틀렛과의 대담. 노화, 남성 건강, 테스토스테론, VO2max 등 장수에 중요한 요소를 다룹니다.","tags":["VO2max","근력","남성건강"]}'),
