  ('means-fix-mito', 83, '{"id":"means-fix-mito","yt":"mxP9Kqik8ac","cat":"mito","cats":["metabolism"],"level":"입문","format":"인터뷰","title":"미토콘드리아와 대사 건강을 고치는 법","orig":"How to FIX Your Mitochondria & Metabolic Health","speaker":"Casey Means","channel":"Podcast","desc":"스탠퍼드 출신 의사 케이시 민스가 미토콘드리아 기능 이상과 대사 건강을 회복하는 생활습관을 설명합니다.","tags":["미토콘드리아","대사건강","생활습관"]}'),
  ('wallace-lecture', 84, '{"id":"wallace-lecture","yt":"2sKKK5Fn_Bg","cat":"mito","cats":["prevention","aging"],"level":"심화","format":"강연","title":"흔한 복합 질환의 미토콘드리아 원인론","orig":"Douglas C Wallace - A mitochondrial etiology of common complex diseases","speaker":"Douglas Wallace","channel":"Distinguished Lecture","desc":"미토콘드리아 의학의 개척자 더글러스 월리스가 당뇨·신경퇴행성 질환·노화 같은 흔한 질환의 바탕에 미토콘드리아 에너지 이상이 있다는 관점을 설명하는 학술 강연.","tags":["미토콘드리아의학","mtDNA","질병"]}'),
  ('osa-mayo-minute', 85, '{"id":"osa-mayo-minute","yt":"kkfYLUR6lKc","cat":"sleep","cats":["heart"],"level":"입문","format":"클립","title":"폐쇄성 수면무호흡증이 있으면 몸에 무슨 일이 생길까","orig":"Mayo Clinic Minute: What happens to your body when you have obstructive sleep apnea?","speaker":"Virend Somers","channel":"Mayo Clinic","desc":"메이오 클리닉 심장내과 버렌드 소머스 교수가 수면 중 숨이 막힐 때 혈압·심장에 어떤 부담이 생기는지 1분 남짓으로 설명합니다.","tags":["수면무호흡","OSA","고혈압"]}'),
  ('osa-medcram', 86, '{"id":"osa-medcram","yt":"slLP3ZxGXHU","cat":"sleep","cats":["heart"],"level":"중급","format":"강연","title":"밤사이 늘어나는 사망 — 폐쇄성 수면무호흡증 해설","orig":"Excess Deaths at Night - Obstructive Sleep Apnea Explained","speaker":"Roger Seheult","channel":"MedCram","desc":"호흡기·수면의학 전문의 로저 세헐트가 폐쇄성 수면무호흡증의 원리, 심혈관 위험, 진단과 치료를 화이트보드로 명쾌하게 정리합니다.","tags":["수면무호흡","OSA","심혈관"]}'),
  ('osa-animation', 87, '{"id":"osa-animation","yt":"N_37HO_V-rk","cat":"sleep","level":"입문","format":"애니메이션","title":"폐쇄성 수면무호흡증은 어떻게 생기나 (애니메이션)","orig":"Obstructive Sleep Apnea","speaker":"의학 애니메이션","channel":"YouTube","desc":"성인 폐쇄성 수면무호흡증의 병태생리 — 잠들면 목의 근육이 이완되어 기도가 좁아지고 막히는 과정을 애니메이션으로 보여줍니다.","tags":["수면무호흡","기도","애니메이션"]}'),
  ('osa-snoring-animation', 88, '{"id":"osa-snoring-animation","yt":"za4tDIyd3fg","cat":"sleep","level":"입문","format":"애니메이션","title":"코골이, 폐쇄성 수면무호흡증과 치료 (애니메이션)","orig":"Snoring, Obstructive Sleep Apnea and Treatment, Animation.","speaker":"의학 애니메이션","channel":"YouTube","desc":"코골이가 생기는 해부학적 원리와 수면무호흡으로 이어지는 과정, 구강 장치 등 치료법을 애니메이션으로 설명합니다.","tags":["코골이","수면무호흡","구강장치"]}'),
  ('cpap-how', 89, '{"id":"cpap-how","yt":"kCUAPvCXUCc","cat":"sleep","level":"입문","format":"클립","title":"양압기(CPAP)는 어떻게 작동할까","orig":"How Does a CPAP Machine Work? - Sleep Apnea Therapies Explained","speaker":"양압기 해설","channel":"YouTube","desc":"수면무호흡증 표준 치료인 양압기(CPAP)의 구성 요소와, 일정한 공기 압력이 ''공기 부목''처럼 기도를 열어두는 원리를 설명합니다.","tags":["양압기","CPAP","수면무호흡"]}'),
  ('cpap-doctor', 90, '{"id":"cpap-doctor","yt":"Xe_ISGRY65M","cat":"sleep","level":"입문","format":"클립","title":"양압기는 실제로 어떻게 작동하나 — 수면의사의 설명","orig":"How CPAP Machines Actually Work","speaker":"양압기 해설","channel":"YouTube","desc":"수면 전문의가 양압기의 작동 원리와 마스크 적응, 흔한 불편(입마름, 압력 적응)을 다루는 방법을 설명합니다.","tags":["양압기","CPAP","마스크"]}'),
  ('osa-mayo-radio', 91, '{"id":"osa-mayo-radio","yt":"OM3XMI6vA-Y","cat":"sleep","level":"입문","format":"팟캐스트","title":"수면무호흡증 — 메이오 클리닉 라디오","orig":"Sleep apnea: Mayo Clinic Radio","speaker":"Mayo Clinic","channel":"Mayo Clinic","desc":"메이오 클리닉 수면 전문의가 수면무호흡증의 증상, 진단, 치료를 이야기합니다. 미국에서만 약 2천만 명이 수면무호흡증을 앓고 있지만 상당수가 모른다고 합니다.","tags":["수면무호흡","진단","치료"]}'),
  ('osa-heart-mayo', 92, '{"id":"osa-heart-mayo","yt":"jpAzH_WjfIo","cat":"heart","cats":["sleep"],"level":"중급","format":"강연","title":"예방 심장학: 수면무호흡증과 심장병","orig":"Preventive Cardiology: Sleep Apnea and Heart Disease","speaker":"Virend Somers","channel":"Mayo Clinic","desc":"버렌드 소머스 교수가 수면무호흡증이 고혈압, 부정맥(심방세동), 심부전, 뇌졸중 위험과 어떻게 연결되는지 설명합니다.","tags":["수면무호흡","심방세동","심장병"]}');
INSERT INTO lt_videos (id, sort, data) VALUES
  ('osa-menopause', 93, '{"id":"osa-menopause","yt":"u2RENZT0Pzk","cat":"sleep","cats":["hormone"],"level":"입문","format":"클립","title":"폐경과 수면무호흡증의 관계","orig":"Mayo Clinic Minute: Understanding the link between menopause and sleep apnea","speaker":"Mayo Clinic","channel":"Mayo Clinic","desc":"폐경 이후 여성에게 수면무호흡증 위험이 높아지는 이유와, 코골이·피로 증상을 그냥 넘기지 말아야 하는 이유를 설명합니다.","tags":["수면무호흡","폐경","여성건강"]}'),
  ('osa-hopkins', 94, '{"id":"osa-hopkins","yt":"TZaQ2xJ9b3g","cat":"sleep","level":"입문","format":"인터뷰","title":"수면무호흡증의 진단과 치료","orig":"Sleep Apnea Diagnosis and Treatment","speaker":"Johns Hopkins","channel":"Johns Hopkins Medicine","desc":"존스홉킨스 수면 전문의 샬린 가말도, 레이철 살라스가 수면다원검사부터 양압기 등 치료까지 수면무호흡증의 진단·치료 과정을 설명합니다.","tags":["수면무호흡","수면다원검사","양압기"]}'),
  ('osa-surgery-hopkins', 95, '{"id":"osa-surgery-hopkins","yt":"2PKyBejsO_w","cat":"sleep","level":"심화","format":"강연","title":"폐쇄성 수면무호흡증 수술 치료의 최신 동향","orig":"What''s New in the Surgical Treatment of Obstructive Sleep Apnea","speaker":"Kevin Motz","channel":"Johns Hopkins Medicine","desc":"존스홉킨스 수면외과 의사 케빈 모츠가 양압기를 쓰기 어려운 환자를 위한 수술·설하신경 자극술 등 치료 옵션을 소개합니다.","tags":["수면무호흡","수술","설하신경자극"]}'),
  ('cpap-ksleep', 96, '{"id":"cpap-ksleep","yt":"bM61RfwGTJk","cat":"sleep","level":"입문","format":"인터뷰","title":"수면무호흡증 치료 장비, 양압치료기 원리와 작동법","orig":"수면무호흡증 치료 장비, 양압치료기 원리와 작동법 [대한수면학회와 함께하는 꿀잠이야기]","speaker":"대한수면학회","channel":"대한수면학회 꿀잠이야기","desc":"원주세브란스병원 호흡기내과 김상하 교수와 강동경희대병원 신경과 신원철 교수가 양압기의 원리와 올바른 사용법을 설명합니다.","tags":["양압기","수면무호흡","한국어"]}'),
  ('cpap-must', 97, '{"id":"cpap-must","yt":"zdtfNvdzrH8","cat":"sleep","level":"입문","format":"인터뷰","title":"수면무호흡증, 양압기 꼭 써야 할까? 원리·종류·적응까지","orig":"[수면연구학회] 수면무호흡증, 양압기 꼭 써야 할까?｜원리·종류·적응까지","speaker":"수면연구학회","channel":"수면연구학회","desc":"양압기(CPAP) 작동 원리, 마스크 종류와 선택 기준, 처음 적응하는 방법을 정리한 한국어 영상.","tags":["양압기","마스크","한국어"]}'),
  ('cpap-pressure', 98, '{"id":"cpap-pressure","yt":"4raXSFW9TGc","cat":"sleep","level":"입문","format":"클립","title":"양압기 사용 전 ''적정 압력'' 처방 받았나요?","orig":"[힐팁TV] 수면무호흡증 치료법 ''양압기'' 사용 전 ''적정 압력'' 처방 받았나요?","speaker":"힐팁TV","channel":"힐팁TV","desc":"양압기 치료에서 개인별 적정 압력 설정(압력 적정 검사)이 왜 중요한지 설명합니다.","tags":["양압기","적정압력","한국어"]}'),
  ('snoring-factcheck', 99, '{"id":"snoring-factcheck","yt":"2K9oxgGS6HE","cat":"sleep","level":"입문","format":"클립","title":"코골이 방지 기구(비강확장기, 입 테이프) 정말 효과 있을까?","orig":"[닥터의 팩트체크] 코골이 방지 기구(비강확장기, 입에 붙이는 테이프) 정말 효과 있을까?","speaker":"윤창호","channel":"분당서울대병원","desc":"분당서울대병원 신경과 윤창호 교수가 시중의 코골이 방지 기구들이 실제로 효과가 있는지, 수면무호흡증이라면 무엇을 해야 하는지 팩트체크합니다.","tags":["코골이","입테이프","한국어"]}'),
  ('sleep-snubh-lecture', 100, '{"id":"sleep-snubh-lecture","yt":"uzWIOsttmC8","cat":"sleep","level":"중급","format":"강연","title":"수면질환의 이해와 치료적 접근 (분당서울대병원 건강강좌)","orig":"수면질환의 이해와 치료적 접근(25.12.12) 정신건강의학과 윤인영 교수, 이비인후과 김정훈 교수, 호흡기내과 조영재 교수","speaker":"분당서울대병원","channel":"분당서울대병원","desc":"정신건강의학과 윤인영, 이비인후과 김정훈, 호흡기내과 조영재 교수가 불면증·수면무호흡증 등 수면질환과 양압기를 포함한 치료법을 설명하는 건강강좌.","tags":["수면질환","수면무호흡","한국어"]}'),
  ('kurz-microbiome', 101, '{"id":"kurz-microbiome","yt":"VzPD009qTN4","cat":"gut","cats":["mental"],"level":"입문","format":"애니메이션","title":"세균은 어떻게 우리 몸을 지배하는가 — 마이크로바이옴","orig":"How Bacteria Rule Over Your Body – The Microbiome","speaker":"Kurzgesagt","channel":"Kurzgesagt – In a Nutshell","desc":"우리 몸에 사는 수조 마리 미생물이 소화·면역은 물론 뇌와 행동에까지 영향을 줄 수 있다는 연구를 애니메이션으로 설명합니다.","tags":["장내미생물","마이크로바이옴","애니메이션"]}'),
  ('knight-ted', 102, '{"id":"knight-ted","yt":"i-icXZ2tMRM","cat":"gut","level":"입문","format":"강연","title":"미생물이 우리를 우리로 만든다","orig":"Rob Knight: How our microbes make us who we are","speaker":"Rob Knight","channel":"TED","desc":"마이크로바이옴 연구의 개척자 롭 나이트가 몸속 미생물이 건강·질병·체중에 미치는 예상 밖의 영향을 소개합니다.","tags":["마이크로바이옴","미생물","TED"]}'),
  ('enders-bowels', 103, '{"id":"enders-bowels","yt":"NMsWFzSr04A","cat":"gut","level":"입문","format":"강연","title":"매력적인 장 — 가장 과소평가된 장기","orig":"Charming bowels","speaker":"Giulia Enders","channel":"TEDx","desc":"베스트셀러 『매력적인 장(Gut)』 저자 줄리아 엔더스가 장이 얼마나 흥미롭고 중요한 기관인지 유쾌하게 이야기합니다.","tags":["장","소화","매력적인장"]}'),
  ('mcauliffe-ted', 104, '{"id":"mcauliffe-ted","yt":"UjGMiChiUFc","cat":"gut","cats":["mental"],"level":"입문","format":"강연","title":"장내 미생물이 성격을 좌우할까?","orig":"Do Gut Microbes Control Your Personality?","speaker":"Kathleen McAuliffe","channel":"TED","desc":"과학 저널리스트 캐슬린 매콜리프가 특정 장내 세균이 기분·행동·성격에까지 영향을 줄 수 있다는 새로운 연구를 소개합니다.","tags":["장뇌축","성격","미생물"]}'),
  ('tedEd-gut-food', 105, '{"id":"tedEd-gut-food","yt":"1sISguPDlhY","cat":"gut","cats":["metabolism"],"level":"입문","format":"애니메이션","title":"먹는 음식은 장에 어떤 영향을 줄까","orig":"How the food you eat affects your gut","speaker":"Shilpa Ravella","channel":"TED-Ed","desc":"장내 세균은 우리가 소화하지 못하는 음식을 분해하고, 영양소를 만들고, 면역을 조절합니다. 식단으로 장내 미생물 균형을 바꾸는 방법을 다룬 TED-Ed 수업.","tags":["식이섬유","장내미생물","애니메이션"]}'),
  ('tedEd-microbes', 106, '{"id":"tedEd-microbes","yt":"1X8p0vhsWRE","cat":"gut","level":"입문","format":"애니메이션","title":"당신은 당신의 미생물이다","orig":"You are your microbes","speaker":"Jessica Green","channel":"TED-Ed","desc":"위장부터 피부까지 우리 몸 곳곳에 사는 미생물과 그 역할을 소개하는 TED-Ed 애니메이션.","tags":["미생물","마이크로바이옴","애니메이션"]}'),
  ('robertson-tedx', 107, '{"id":"robertson-tedx","yt":"awtmTJW9ic8","cat":"gut","cats":["mental"],"level":"입문","format":"강연","title":"생각을 위한 음식: 배가 뇌를 조종하는 방법","orig":"Food for thought: How your belly controls your brain","speaker":"Ruairi Robertson","channel":"TEDx Talks","desc":"영양학 연구자 루어리 로버트슨이 장과 뇌가 신경·호르몬·면역으로 연결된 ''장-뇌 축''과 식단이 정신건강에 미치는 영향을 설명합니다.","tags":["장뇌축","정신건강","식단"]}'),
  ('sonnenburg-huberman', 108, '{"id":"sonnenburg-huberman","yt":"T1w5vpPU8As","cat":"gut","cats":["metabolism"],"level":"중급","format":"팟캐스트","title":"저스틴 소넨버그: 장 건강을 만들고 지키고 회복하는 법","orig":"Dr. Justin Sonnenburg: How to Build, Maintain & Repair Gut Health","speaker":"Justin Sonnenburg","channel":"Huberman Lab","desc":"스탠퍼드 미생물학자 저스틴 소넨버그(#62). 발효식품과 식이섬유가 장내 미생물 다양성과 염증 지표에 미친 영향을 본 스탠퍼드 연구를 중심으로 장 건강 전략을 다룹니다.","tags":["발효식품","식이섬유","염증"]}'),
