  ('menopause-kbs', 161, '{"id":"menopause-kbs","yt":"qCE45vEyqcs","cat":"hormone","level":"입문","format":"다큐","title":"호르몬으로 인한 갱년기 증후군의 증상과 치료","orig":"호르몬으로 인한 갱년기증후군의 증상과 치료 방법 (KBS 20221228 방송)","speaker":"KBS 생로병사의 비밀","channel":"KBS","desc":"세브란스병원 산부인과 의료진이 출연해 갱년기 증상과 호르몬 치료의 득과 실을 짚어보는 KBS 방송.","tags":["갱년기","호르몬치료","한국어"]}'),
  ('ko-jung-diet', 162, '{"id":"ko-jung-diet","yt":"XCRAVay3-xI","cat":"aging","cats":["metabolism"],"level":"입문","format":"인터뷰","title":"늙기 싫은 현대인을 위한 가장 완벽한 식사법","orig":"늙기 싫은 현대인을 위한 가장 완벽한 식사법","speaker":"정희원","channel":"YouTube","desc":"서울아산병원 노년내과 정희원 교수가 노화 속도를 늦추는 식사법 — 정제 탄수화물 줄이기, 충분한 단백질, 채소·통곡물 위주의 ''저속노화 식단''을 설명합니다.","tags":["저속노화","식사법","한국어"]}'),
  ('ko-jung-slow', 163, '{"id":"ko-jung-slow","yt":"4w8kuWJwDg8","cat":"aging","cats":["bluezones","sleep"],"level":"입문","format":"인터뷰","title":"천천히 늙으려면 이렇게 먹고, 자고, 사셔야 합니다 [몰아보기]","orig":"천천히 늙으려면 이렇게 먹고, 자고, 사셔야 합니다 [몰아보기]","speaker":"정희원","channel":"YouTube","desc":"정희원 교수가 식사·수면·운동·스트레스 관리까지 저속노화 생활습관을 한 번에 정리합니다.","tags":["저속노화","생활습관","한국어"]}'),
  ('ko-jung-lecture', 164, '{"id":"ko-jung-lecture","yt":"GsrdB_va0uo","cat":"aging","level":"입문","format":"강연","title":"[대한민국 명강의] 저속노화","orig":"[대한민국 명강의] 저속노화","speaker":"정희원","channel":"YouTube","desc":"노쇠와 가속노화를 막기 위해 일상에서 실천할 수 있는 저속노화 원칙을 다룬 강연. 부모님과 함께 보기 좋은 영상입니다.","tags":["저속노화","노쇠","한국어"]}'),
  ('ko-jung-checkup', 165, '{"id":"ko-jung-checkup","yt":"sVujCGvMaaM","cat":"prevention","cats":["aging"],"level":"입문","format":"인터뷰","title":"매년 받는 건강검진, ''이 나이 이후로는'' 받지 마세요","orig":"매년 받는 건강검진, ''이 나이 이후로는'' 받지 마세요","speaker":"정희원","channel":"YouTube","desc":"나이에 따라 필요한 검진과 오히려 줄여야 할 검진 — 과잉 검진의 문제를 노년내과 관점에서 설명합니다.","tags":["건강검진","과잉진료","한국어"]}'),
  ('ko-kbs-longevity', 166, '{"id":"ko-kbs-longevity","yt":"t0dlB4TCE50","cat":"aging","cats":["bluezones"],"level":"입문","format":"다큐","title":"25년간 추적한 장수의 비밀 — 병에서 벗어나 사는 법","orig":"25년간 추적한 장수의 비밀 — 병에서 벗어나 사는 법","speaker":"KBS 생로병사의 비밀","channel":"KBS 생로병사의 비밀","desc":"세계 백세인 연구와 국내외 현장 취재로, 질병과 노화 속에서도 삶의 주도권을 지키며 오래 사는 방법을 살펴봅니다.","tags":["장수","백세인","한국어"]}'),
  ('ko-kbs-young-elders', 167, '{"id":"ko-kbs-young-elders","yt":"86pYJNClxIg","cat":"aging","cats":["bluezones"],"level":"입문","format":"다큐","title":"노화의 원인과 젊은 노인들의 생활 습관","orig":"노화의 원인과 젊은 노인들의 생활 습관","speaker":"KBS 생로병사의 비밀","channel":"KBS 생로병사의 비밀","desc":"같은 나이에도 노화지수가 낮은 ''슈퍼 시니어''들은 무엇이 다른지, 노화를 앞당기는 원인과 생활습관을 다룹니다.","tags":["노화지수","슈퍼시니어","한국어"]}'),
  ('ko-kbs-bluezone2', 168, '{"id":"ko-kbs-bluezone2","yt":"_tkynKEAL6o","cat":"bluezones","cats":["metabolism"],"level":"입문","format":"다큐","title":"블루존의 늙지 않는 비밀 2편 — 적게, 균형 있게, 장수 유전자를 깨워라","orig":"블루존의 늙지 않는 비밀 2편 — 적게, 균형 있게, 장수 유전자를 깨워라","speaker":"KBS 생로병사의 비밀","channel":"KBS 생로병사의 비밀","desc":"2021 신년기획. 블루존 사람들의 소식(少食)과 균형 잡힌 식단이 장수와 어떤 관련이 있는지 취재했습니다.","tags":["블루존","소식","한국어"]}'),
  ('ko-kbs-telomere', 169, '{"id":"ko-kbs-telomere","yt":"_HbBhWCsD10","cat":"aging","level":"입문","format":"다큐","title":"노화의 척도를 알 수 있는 세포, 텔로미어","orig":"노화의 척도를 알 수 있는 세포, 텔로미어","speaker":"KBS 생로병사의 비밀","channel":"KBS 생로병사의 비밀","desc":"세포 노화의 지표로 알려진 텔로미어와 생활습관의 관계를 소개합니다.","tags":["텔로미어","세포노화","한국어"]}'),
  ('ko-snuh-insomnia', 170, '{"id":"ko-snuh-insomnia","yt":"p13PXFhU0Bs","cat":"sleep","level":"입문","format":"인터뷰","title":"불면증 치료하고 잠을 잘 자는 방법","orig":"불면증 치료하고 잠을 잘 자는 방법","speaker":"이유진","channel":"서울대병원","desc":"서울대병원 정신건강의학과 이유진 교수(수면의학센터장)가 불면증·코골이 등 수면장애에서 벗어나는 방법과 숙면 요령을 알려줍니다.","tags":["불면증","숙면","한국어"]}'),
  ('ko-amc-sleep-habit', 171, '{"id":"ko-amc-sleep-habit","yt":"TGWFGvLHPEA","cat":"sleep","level":"입문","format":"강연","title":"수면 습관의 힘","orig":"수면 습관의 힘","speaker":"주연호","channel":"서울아산병원","desc":"서울아산병원 정신건강의학과 주연호 교수의 ''꼰대 의사의 정신과 얘기'' 45화. 잠을 바꾸는 생활 속 수면 습관을 이야기합니다.","tags":["수면습관","수면위생","한국어"]}'),
