  ('ko-amc-insomnia-dx', 173, '{"id":"ko-amc-insomnia-dx","yt":"6EZM90lx2HQ","cat":"sleep","level":"중급","format":"강연","title":"불면증의 진단과 치료","orig":"불면증의 진단과 치료","speaker":"정석훈","channel":"서울아산병원","desc":"동아-아산 건강강좌. 서울아산병원 정신건강의학과 정석훈 교수가 불면증의 원인, 진단, 인지행동치료와 약물치료를 설명합니다.","tags":["불면증","인지행동치료","한국어"]}'),
  ('ko-amc-elder-depression', 174, '{"id":"ko-amc-elder-depression","yt":"ATddaeikbuE","cat":"mental","cats":["sleep"],"level":"입문","format":"강연","title":"노년기 우울증과 불면증","orig":"노년기 우울증과 불면증","speaker":"장석훈","channel":"서울아산병원","desc":"서울아산병원 정신건강의학과 장석훈 교수가 노년기에 흔한 우울증과 불면증의 특징, 치료, 일상 관리법을 설명합니다.","tags":["노인우울증","불면증","한국어"]}'),
