  ('ko-amc-lipid', 178, '{"id":"ko-amc-lipid","yt":"ZPkrSEJ0ldc","cat":"heart","level":"입문","format":"인터뷰","title":"고지혈증, 제대로 알기","orig":"고지혈증, 제대로 알기","speaker":"한기훈","channel":"서울아산병원","desc":"서울아산병원 심장내과 한기훈 교수가 고지혈증(이상지질혈증)의 위험과 치료 기준, 약물 치료를 설명합니다 (홍혜걸의 인사이트 인터뷰).","tags":["고지혈증","LDL","한국어"]}'),
  ('ko-amc-metsyn', 179, '{"id":"ko-amc-metsyn","yt":"uyCONWekvKw","cat":"heart","cats":["metabolism"],"level":"입문","format":"강연","title":"대사증후군과의 전쟁","orig":"대사증후군과의 전쟁","speaker":"한기훈","channel":"서울아산병원","desc":"서울아산병원 심장병원 온라인 건강강좌. 복부비만·고혈압·고혈당·이상지질혈증이 겹치는 대사증후군과 콜레스테롤 관리법.","tags":["대사증후군","콜레스테롤","한국어"]}'),
  ('ko-sev-lipid-bp', 180, '{"id":"ko-sev-lipid-bp","yt":"SNrQY56Z4yc","cat":"heart","level":"입문","format":"인터뷰","title":"이상지질혈증과 고혈압 정복하기","orig":"이상지질혈증과 고혈압 정복하기","speaker":"홍그루","channel":"세브란스병원","desc":"세브란스병원 심장내과 홍그루 교수가 이상지질혈증과 고혈압의 관리, 약 복용의 중요성을 설명합니다.","tags":["이상지질혈증","고혈압","한국어"]}'),
  ('ko-sev-triple', 181, '{"id":"ko-sev-triple","yt":"R6jp4McBeW8","cat":"heart","cats":["metabolism"],"level":"입문","format":"인터뷰","title":"''한통속'' 고혈압, 고지혈증, 당뇨 한 번에 잡는 법","orig":"''한통속'' 고혈압, 고지혈증, 당뇨 한 번에 잡는 법","speaker":"세브란스병원","channel":"세브란스병원","desc":"혈관을 함께 망가뜨리는 고혈압·고지혈증·당뇨를 한꺼번에 관리하는 방법 (PEOPLE in 세브란스).","tags":["고혈압","당뇨","한국어"]}'),
  ('ko-sev-bp', 182, '{"id":"ko-sev-bp","yt":"bwbb8BC2xtQ","cat":"heart","level":"입문","format":"인터뷰","title":"세브란스 명의들이 말하는 고혈압 몰아 보기","orig":"세브란스 명의들이 말하는 고혈압 몰아 보기","speaker":"세브란스병원","channel":"세브란스병원","desc":"고혈압의 날 특집. 혈압약 복용법과 생활습관 개선법을 세브란스 교수진이 정리합니다.","tags":["고혈압","혈압약","한국어"]}');
