  ('ko-smc-lipid-drug', 183, '{"id":"ko-smc-lipid-drug","yt":"f1DWCMd055Q","cat":"heart","level":"중급","format":"인터뷰","title":"고지혈증 치료의 획기적인 신약","orig":"고지혈증 치료의 획기적인 신약","speaker":"권현철","channel":"삼성서울병원","desc":"삼성서울병원 순환기내과 권현철 교수가 스타틴 부작용과 이를 보완하는 새로운 고지혈증 치료제를 소개합니다.","tags":["고지혈증","신약","한국어"]}'),
